# Code Generated by Sidekick is for learning and experimentation purposes only.

import logging
import time

import stripe
from tenacity import (
    before_sleep_log,
    retry,
    retry_if_exception_type,
    stop_after_attempt,
    wait_exponential,
)

from bank_connector.app.config import settings
from bank_connector.app.processors.base import BaseProcessor
from bank_connector.app.schemas.connector import (
    AuthorizeRequest,
    CaptureRequest,
    ProcessorResponse,
    RefundRequest,
    VoidRequest,
)

logger = logging.getLogger(__name__)

stripe.api_key = settings.stripe_secret_key
stripe.api_version = settings.stripe_api_version
stripe.max_network_retries = 0

RETRYABLE_ERRORS = (
    stripe.error.APIConnectionError,
    stripe.error.APIError,
    stripe.error.RateLimitError,
)

NON_RETRYABLE_ERRORS = (
    stripe.error.CardError,
    stripe.error.InvalidRequestError,
    stripe.error.AuthenticationError,
    stripe.error.PermissionError,
    stripe.error.IdempotencyError,
)

# Stripe test tokens - maps card numbers to Stripe tokens
# This is required in test mode unless raw card API is enabled
TEST_TOKEN_MAP = {
    # Success cards
    "4242424242424242": "tok_visa",
    "4000056655440028": "tok_visa_debit",
    "5555555555554444": "tok_mastercard",
    "5200828282828210": "tok_mastercard_debit",
    "5105105105105100": "tok_mastercard_prepaid",
    "378282246310005":  "tok_amex",
    "371449635398431":  "tok_amex",
    "6011111111111117": "tok_discover",
    "3056930009020004": "tok_diners",
    "36227206271667":   "tok_diners",
    "3566002020360505": "tok_jcb",
    "6200000000000005": "tok_unionpay",
    # Decline cards
    "4000000000000002": "tok_chargeDeclined",
    "4000000000000069": "tok_chargeDeclinedExpiredCard",
    "4000000000000127": "tok_chargeDeclinedIncorrectCvc",
    "4000000000000119": "tok_chargeDeclinedProcessingError",
    "4000000000009995": "tok_chargeDeclinedInsufficientFunds",
    "4000000000009987": "tok_chargeDeclinedLostCard",
    "4000000000009979": "tok_chargeDeclinedStolenCard",
    "4100000000000019": "tok_chargeDeclinedFraudulent",
}


class StripeProcessor(BaseProcessor):

    @property
    def name(self) -> str:
        return "stripe"

    def _get_payment_method(self, card_number: str, exp_month: int, exp_year: int, cvc: str):
        """
        Get Stripe token for test mode.
        In production: use Stripe.js or Elements to tokenize on frontend.
        """
        token_id = TEST_TOKEN_MAP.get(card_number, "tok_visa")
        logger.info(f"Using Stripe test token: {token_id} for card: ***{card_number[-4:]}")
        return token_id

    @retry(
        retry=retry_if_exception_type(RETRYABLE_ERRORS),
        stop=stop_after_attempt(settings.max_retries),
        wait=wait_exponential(
            multiplier=settings.retry_wait_seconds,
            max=settings.retry_max_wait_seconds,
        ),
        before_sleep=before_sleep_log(logger, logging.WARNING),
        reraise=True,
    )
    async def authorize(self, request: AuthorizeRequest) -> ProcessorResponse:
        start = time.time()

        try:
            logger.info(
                f"Stripe authorize: payment={request.payment_id} "
                f"amount={request.amount} currency={request.currency}",
            )

            # Get test token for this card number
            token = self._get_payment_method(
                request.card.number,
                request.card.exp_month,
                request.card.exp_year,
                request.card.cvc,
            )

            # Create PaymentIntent using token
            intent = stripe.PaymentIntent.create(
                amount=request.amount,
                currency=request.currency.lower(),
                payment_method_data={
                    "type": "card",
                    "card": {"token": token},
                },
                capture_method="manual",
                confirm=True,
                automatic_payment_methods={
                    "enabled": True,
                    "allow_redirects": "never",
                },
                description=request.description or f"Payment {request.payment_id}",
                metadata={
                    "payment_id": request.payment_id,
                    "merchant_id": request.merchant_id,
                    **(request.metadata or {}),
                },
                idempotency_key=request.idempotency_key,
            )

            duration = int((time.time() - start) * 1000)
            logger.info(
                f"Stripe authorize success: intent={intent.id} "
                f"status={intent.status} duration={duration}ms",
            )

            # Get card details from intent
            card_last4 = None
            card_brand = None
            if intent.payment_method:
                try:
                    pm = stripe.PaymentMethod.retrieve(intent.payment_method)
                    card_last4 = pm.card.last4 if pm.card else None
                    card_brand = pm.card.brand if pm.card else None
                except Exception:
                    logger.debug("Could not retrieve card details from payment method", exc_info=True)

            return ProcessorResponse(
                success=True,
                processor=self.name,
                processor_id=intent.id,
                authorization_code=intent.id,
                amount=intent.amount,
                currency=intent.currency,
                card_last4=card_last4 or request.card.number[-4:],
                card_brand=card_brand or "unknown",
                raw_response={
                    "intent_id": intent.id,
                    "intent_status": intent.status,
                    "payment_method": intent.payment_method,
                    "duration_ms": duration,
                },
            )

        except stripe.error.CardError as e:
            duration = int((time.time() - start) * 1000)
            err = e.error
            logger.warning(
                f"Stripe card declined: payment={request.payment_id} "
                f"code={err.code} decline_code={err.decline_code}",
            )
            return ProcessorResponse(
                success=False,
                processor=self.name,
                failure_code=err.code,
                failure_message=err.message,
                decline_code=err.decline_code,
                raw_response={
                    "error_type": "card_error",
                    "code": err.code,
                    "decline_code": err.decline_code,
                    "duration_ms": duration,
                },
            )

        except NON_RETRYABLE_ERRORS as e:
            duration = int((time.time() - start) * 1000)
            logger.exception(f"Stripe non-retryable error: {e}")
            return ProcessorResponse(
                success=False,
                processor=self.name,
                failure_code="processor_error",
                failure_message=str(e),
                raw_response={
                    "error_type": type(e).__name__,
                    "duration_ms": duration,
                },
            )

    async def capture(self, request: CaptureRequest) -> ProcessorResponse:
        start = time.time()
        try:
            logger.info(f"Stripe capture: payment={request.payment_id} processor_id={request.processor_id}")

            intent = stripe.PaymentIntent.capture(
                request.processor_id,
                amount_to_capture=request.amount,
                idempotency_key=request.idempotency_key,
            )

            duration = int((time.time() - start) * 1000)
            logger.info(f"Stripe capture success: intent={intent.id} duration={duration}ms")

            return ProcessorResponse(
                success=True,
                processor=self.name,
                processor_id=intent.id,
                capture_reference=intent.latest_charge,
                amount=intent.amount_received,
                currency=intent.currency,
                raw_response={
                    "intent_id": intent.id,
                    "intent_status": intent.status,
                    "charge_id": intent.latest_charge,
                    "duration_ms": duration,
                },
            )

        except stripe.error.InvalidRequestError as e:
            logger.exception(f"Stripe capture invalid: {e}")
            return ProcessorResponse(
                success=False,
                processor=self.name,
                failure_code="capture_failed",
                failure_message=str(e),
            )

        except RETRYABLE_ERRORS:
            raise

    async def refund(self, request: RefundRequest) -> ProcessorResponse:
        start = time.time()
        try:
            logger.info(f"Stripe refund: payment={request.payment_id} processor_id={request.processor_id}")

            refund_params = {"payment_intent": request.processor_id}
            if request.idempotency_key:
                refund_params["idempotency_key"] = request.idempotency_key
            if request.amount:
                refund_params["amount"] = request.amount
            if request.reason:
                reason_map = {
                    "duplicate": "duplicate",
                    "fraud": "fraudulent",
                    "customer_request": "requested_by_customer",
                }
                refund_params["reason"] = reason_map.get(request.reason, "requested_by_customer")

            refund = stripe.Refund.create(**refund_params)

            duration = int((time.time() - start) * 1000)
            logger.info(f"Stripe refund success: refund={refund.id} duration={duration}ms")

            return ProcessorResponse(
                success=True,
                processor=self.name,
                processor_id=refund.id,
                refund_reference=refund.id,
                amount=refund.amount,
                currency=refund.currency,
                raw_response={
                    "refund_id": refund.id,
                    "refund_status": refund.status,
                    "duration_ms": duration,
                },
            )

        except stripe.error.InvalidRequestError as e:
            logger.exception(f"Stripe refund invalid: {e}")
            return ProcessorResponse(
                success=False,
                processor=self.name,
                failure_code="refund_failed",
                failure_message=str(e),
            )

        except RETRYABLE_ERRORS:
            raise

    async def void(self, request: VoidRequest) -> ProcessorResponse:
        start = time.time()
        try:
            logger.info(f"Stripe void: payment={request.payment_id} processor_id={request.processor_id}")

            intent = stripe.PaymentIntent.cancel(
                request.processor_id,
                cancellation_reason="requested_by_customer",
                idempotency_key=request.idempotency_key,
            )

            duration = int((time.time() - start) * 1000)
            logger.info(f"Stripe void success: intent={intent.id} duration={duration}ms")

            return ProcessorResponse(
                success=True,
                processor=self.name,
                processor_id=intent.id,
                void_reference=f"void_{intent.id}",
                raw_response={
                    "intent_id": intent.id,
                    "intent_status": intent.status,
                    "duration_ms": duration,
                },
            )

        except stripe.error.InvalidRequestError as e:
            logger.exception(f"Stripe void invalid: {e}")
            return ProcessorResponse(
                success=False,
                processor=self.name,
                failure_code="void_failed",
                failure_message=str(e),
            )

        except RETRYABLE_ERRORS:
            raise

    async def health_check(self) -> bool:
        try:
            stripe.Account.retrieve()
            return True
        except stripe.error.AuthenticationError:
            return False
        except Exception: # noqa: BLE001
            return False
